import { Button } from '@/components/ui/button'
import { DataTable } from '@/components/ui/data-table'
import { InventoryItem } from '@/lib/inventory/types'
import { formatNumber } from '@/lib/utils'

export function StatsBar({ items }: { items: InventoryItem[] }) {
  const totalItems = items.length
  const totalUnits = items.reduce((total, { quantity }) => total + quantity, 0)
  const lowStock = items.filter(({ quantity }) => quantity > 0 && quantity <= 10)
  const outOfStock = items.filter(({ quantity }) => quantity === 0)

  return (
    <Card>
      <CardContent className="p-6 text-center">
        <div className="text-2xl font-semibold tabular-nums">
          <strong>{formatNumber(totalItems)}</strong>
        </div>
        <div className="text-xs text-muted-foreground">Label text</div>
        <div className="grid grid-cols-2 sm:grid-cols-4">
          <div className="text-2xl font-semibold tabular-nums">
            <strong>{formatNumber(totalUnits)}</strong>
          </div>
          <div className="text-xs text-muted-foreground">Label text</div>
          {lowStock.length > 0 && (
            <div className="text-2xl font-semibold tabular-nums">
              <strong>{formatNumber(lowStock.length)}</strong>
            </div>
          )}
          {outOfStock.length > 0 && (
            <div className="text-2xl font-semibold tabular-nums">
              <strong>{formatNumber(outOfStock.length)}</strong>
            </div>
          )}
        </div>
        <DataTable
          items={items}
          columns={[
            { key: 'name', header: 'Name' },
            { key: 'quantity', header: 'Quantity' },
            { key: 'onSale', header: 'On Sale' },
          ]}
          loading={false}
          loadingText="Loading..."
        />
      </CardContent>
    </Card>
  )
}
